package main

import (
    "crypto/rand"
    "encoding/base64"
    "encoding/json"
    "fmt"
    "html/template"
    "io"
    "net"
    "net/http"
    "net/url"
    "os"
    "os/exec"
    "path/filepath"
    "runtime"
    "strings"

    "github.com/getlantern/systray"
)

type identity struct { AgentID string `json:"agent_id"`; AgentToken string `json:"agent_token"` }
type config struct { ServerURL string `json:"server_url"` }
type client struct { identity identity; server string; session string; baseURL string }
type createTicket struct { Title string `json:"title"`; Description string `json:"description"`; Priority string `json:"priority"`; Category string `json:"category,omitempty"`; Requester string `json:"requester,omitempty"` }

const page = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bhudi Support</title><style>body{font-family:Segoe UI,Arial;margin:0;background:#f1f5f9;color:#0f172a}.wrap{max-width:760px;margin:40px auto;background:#fff;padding:28px;border-radius:14px;box-shadow:0 10px 30px #0001}label{display:block;font-weight:600;margin:14px 0 6px}input,textarea,select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #cbd5e1;border-radius:8px}textarea{min-height:120px}button{margin-top:18px;padding:11px 18px;border:0;border-radius:8px;background:#4f46e5;color:#fff;font-weight:600;cursor:pointer}.muted{color:#64748b;font-size:13px}.ok{background:#ecfdf5;color:#047857;padding:10px;border-radius:8px;margin-top:14px}.err{background:#fef2f2;color:#b91c1c;padding:10px;border-radius:8px;margin-top:14px}.ticket{border:1px solid #e2e8f0;padding:12px;border-radius:9px;margin-top:10px}</style></head><body><div class="wrap"><h1>Bhudi Support</h1><p class="muted">This request is automatically associated with this computer and your customer account.</p><form id="f"><label>Subject</label><input id="title" required maxlength="512"><label>Description</label><textarea id="description" required></textarea><label>Priority</label><select id="priority"><option>low</option><option selected>medium</option><option>high</option><option>critical</option></select><label>Category</label><input id="category" placeholder="e.g. Email, Printer, Network"><label>Your name/email</label><input id="requester"><button>Open Ticket</button></form><div id="msg"></div><h2>My Tickets</h2><div id="tickets" class="muted">Loading…</div></div><script>const S={{.Session}};async function api(path,opt={}){opt.headers=Object.assign({'X-Bhudi-Session':S},opt.headers||{});const r=await fetch(path,opt),t=await r.text();let d={};try{d=JSON.parse(t)}catch{}if(!r.ok)throw new Error(d.detail||t||r.statusText);return d}function esc(v){return String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]))}async function load(){try{const d=await api('/api/tickets'),x=d.tickets||[];document.getElementById('tickets').innerHTML=x.length?x.map(t=>'<div class="ticket"><b>'+esc(t.number)+'</b> — '+esc(t.title)+'<br><span class="muted">'+esc(t.status)+' · '+esc(t.priority)+'</span></div>').join(''):'No tickets yet.'}catch(e){document.getElementById('tickets').textContent=e.message}}document.getElementById('f').onsubmit=async e=>{e.preventDefault();const m=document.getElementById('msg');m.className='muted';m.textContent='Submitting…';try{const d=await api('/api/tickets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:document.getElementById('title').value,description:document.getElementById('description').value,priority:document.getElementById('priority').value,category:document.getElementById('category').value,requester:document.getElementById('requester').value})});m.className='ok';m.textContent='Ticket '+esc(d.number)+' created.';e.target.reset();document.getElementById('priority').value='medium';load()}catch(err){m.className='err';m.textContent=err.message}};load();</script></body></html>`

func main(){c,err:=loadClient();if err!=nil{fmt.Fprintln(os.Stderr,"Bhudi Support Client:",err);os.Exit(1)};ln,err:=net.Listen("tcp","127.0.0.1:0");if err!=nil{fmt.Fprintln(os.Stderr,err);os.Exit(1)};c.baseURL="http://"+ln.Addr().String();mux:=http.NewServeMux();mux.HandleFunc("/",c.page);mux.HandleFunc("/api/tickets",c.ticketAPI);go func(){_=http.Serve(ln,mux)}();systray.Run(c.ready,func(){_=ln.Close()})}
func loadClient()(*client,error){dir:=dataDir();ib,err:=os.ReadFile(filepath.Join(dir,"agent_identity.json"));if err!=nil{return nil,fmt.Errorf("agent identity unavailable: %w",err)};var id identity;if err=json.Unmarshal(ib,&id);err!=nil||id.AgentID==""||id.AgentToken==""{return nil,fmt.Errorf("invalid agent identity")};cb,err:=os.ReadFile(filepath.Join(dir,"agent_config.json"));if err!=nil{return nil,fmt.Errorf("agent configuration unavailable: %w",err)};var cfg config;if err=json.Unmarshal(cb,&cfg);err!=nil||strings.TrimSpace(cfg.ServerURL)==""{return nil,fmt.Errorf("invalid agent configuration")};s:=make([]byte,32);if _,err=rand.Read(s);err!=nil{return nil,err};return &client{identity:id,server:strings.TrimRight(cfg.ServerURL,"/"),session:base64.RawURLEncoding.EncodeToString(s)},nil}
func dataDir()string{base:=os.Getenv("ProgramData");if base==""{base=os.Getenv("LOCALAPPDATA")};if base==""{base="."};return filepath.Join(base,"Bhudi","Agent")}
func(c *client)ready(){systray.SetTitle("Bhudi");systray.SetTooltip("Bhudi Support");systray.SetIcon(icon());open:=systray.AddMenuItem("Open Ticket","Open a Bhudi support ticket");tickets:=systray.AddMenuItem("My Tickets","View your Bhudi tickets");systray.AddSeparator();quit:=systray.AddMenuItem("Exit","Exit Bhudi Support");go func(){for{select{case<-open.ClickedCh:c.open();case<-tickets.ClickedCh:c.open();case<-quit.ClickedCh:systray.Quit();return}}}()}
func(c *client)open(){target:=c.baseURL+"/?session="+url.QueryEscape(c.session);if runtime.GOOS=="windows"{_=exec.Command("rundll32","url.dll,FileProtocolHandler",target).Start()}else{_=exec.Command("xdg-open",target).Start()}}
func(c *client)authorized(w http.ResponseWriter,r *http.Request)bool{if r.Header.Get("X-Bhudi-Session")!=c.session{http.Error(w,"unauthorized",http.StatusUnauthorized);return false};return true}
func(c *client)page(w http.ResponseWriter,r *http.Request){session:=r.URL.Query().Get("session");if session!=c.session{if !c.authorized(w,r){return};session=c.session};w.Header().Set("Cache-Control","no-store");_=template.Must(template.New("p").Parse(page)).Execute(w,map[string]string{"Session":session})}
func(c *client)ticketAPI(w http.ResponseWriter,r *http.Request){if !c.authorized(w,r){return};endpoint:=c.server+"/api/v1/agent-support/tickets?agent_id="+url.QueryEscape(c.identity.AgentID);var req *http.Request;var err error;switch r.Method{case http.MethodPost:var payload createTicket;if err=json.NewDecoder(r.Body).Decode(&payload);err!=nil{http.Error(w,err.Error(),400);return};body,e:=json.Marshal(payload);if e!=nil{http.Error(w,e.Error(),500);return};req,err=http.NewRequest(http.MethodPost,endpoint,strings.NewReader(string(body)));if err==nil{req.Header.Set("Content-Type","application/json")};case http.MethodGet:req,err=http.NewRequest(http.MethodGet,endpoint,nil);default:http.Error(w,"method not allowed",405);return};if err!=nil{http.Error(w,err.Error(),500);return};req.Header.Set("X-Bhudi-Agent-Token",c.identity.AgentToken);res,err:=http.DefaultClient.Do(req);if err!=nil{http.Error(w,err.Error(),502);return};defer res.Body.Close();w.Header().Set("Content-Type","application/json");w.WriteHeader(res.StatusCode);_,_=io.Copy(w,res.Body)}
func icon()[]byte{b,_:=base64.StdEncoding.DecodeString("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=");return b}
